entries[265330] = { ["name"] = "Satchel of Shining Curiosities", ["text"] = "Binds when picked up\n\"The satchel trembles with the weight of curious and shining commodities...\"\n<Right Click to Open>" }
entries[265414] = { ["name"] = "Platinum Amber", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Encase yourself in restorative amber, restoring 300000 health and 300000 mana over 10 sec. (1 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (1 Min Cooldown)" }
entries[265415] = { ["name"] = "Platinum Vial of Polyformic Acid", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Drink to apply the Polyformic Acid transformation. (5 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (5 Min Cooldown)\n\"Good news! The vial is flowing again.\"" }
entries[265416] = { ["name"] = "Platinum Battle Banner", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Blend into the shadows for 1 sec and summon a Scarlet Crusader. The Crusader will draw the attention of nearby monsters and run into the distance. (10 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (10 Min Cooldown)" }
entries[265417] = { ["name"] = "Platinum Battle Horn", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Blast a blaring horn, attracting enemies within 40 yards. (2 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (2 Min Cooldown)" }
entries[265418] = { ["name"] = "Platinum Rod of Ambershaping", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Encases the target in amber, preventing all action for up to 1 min. Any damage caused will break the amber. (5 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (5 Min Cooldown)" }
entries[265419] = { ["name"] = "Platinum Potion of Invisibility", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Gives the imbiber invisibility for 18 sec. (5 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (5 Min Cooldown)" }
entries[265573] = { ["name"] = "Platinum Sacrificial Dagger", ["text"] = "Binds when picked up\nUnique\nToy\nUse: A faint whispering can be heard inside of your own head. The dagger bids you to thrust it deep into your heart. Do you dare comply? (8 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (8 Min Cooldown)\n\"A ceremonial dagger with the bloody initials T.R.O etched on the hilt. A fourth letter is marred beyond recognition.\"" }
entries[265774] = { ["name"] = "Platinum Boots of Expeditious Retreat", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Engage the rocket boots to greatly increase your speed. (5 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (5 Min Cooldown)\n\"*WARNING* Do not exceed speeds of 1772.\"" }
entries[265780] = { ["name"] = "Platinum \"Little Ale\"", ["text"] = "Binds when picked up\nUnique\nToy\nUse: A strong and inspiring glass of exotic beer. (10 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (10 Min Cooldown)\n\"One of the more imaginative drinks to be sold from Stormstout. It is difficult to understand how small this glass of ale is. Each glass has the initials \"A.E\" engraved on the base.\"" }
entries[265783] = { ["name"] = "Tabard of Fury", ["text"] = "Binds when picked up\nTabard" }
entries[265784] = { ["name"] = "Tabard of Brilliance", ["text"] = "Binds when picked up\nTabard" }
entries[265785] = { ["name"] = "Tabard of the Void", ["text"] = "Binds when picked up\nTabard" }
entries[265786] = { ["name"] = "Demon Hunter's Aspect", ["text"] = "Binds when picked up\nToy\nUse: Resemble a demon hunter for 5 min. (30 Min Cooldown)" }
entries[265787] = { ["name"] = "Magic Rooster Egg", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 40\nRequires Journeyman Riding\nUse: Teaches you how to summon this mount." }
entries[265788] = { ["name"] = "Wooly White Rhino", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 40\nRequires Journeyman Riding\nUse: Teaches you how to summon this mount." }
entries[265789] = { ["name"] = "Eye of the Legion", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss an Eye of the Legion." }
entries[265851] = { ["name"] = "Platinum Drums of Speed", ["text"] = "Binds when picked up\nToy\nUse: Increases movement speed of party members within 40 yards by 15%. Lasts 30 sec. Drums can be used while shapeshifted. (2 Min Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (2 Min Cooldown)\n50 Charges" }
entries[266129] = { ["name"] = "WoW Classic - Pet - Alligator Sun Godlet [Sa'bak's Favored]", ["text"] = "Binds when picked up\nUse:\nRight Click to summon and dismiss Sa'bak's Favored." }
entries[266272] = { ["name"] = "Satchel of Stone Shards", ["text"] = "Binds to account\n\"Contains 10 August Stone Shards\"" }
entries[266273] = { ["name"] = "Cache of Celestial Chance", ["text"] = "Binds to account\n\"You see something rustling inside... maybe today is your lucky day!\"" }
entries[266999] = { ["name"] = "Swift Yak Pelt", ["text"] = "Binds when picked up\nUnique\nToy\nMount\nRequires Level 85\nUse: Summons a ridable rampaging yak. This is a very, VERY fast mount. (3 Sec Cooldown)\n\nOnly usable in Challenge Mode Dungeons. (3 Sec Cooldown)\n\"Rumor has it a fabled Yak was cared for by a local farmer after its Kun-Lai glide involved a collision with a tree.\"" }
entries[267174] = { ["name"] = "Ensemble: Twilight's Hammer Regalia", ["text"] = "Binds when picked up\nUse: Collect the appearances of the Twilight's Hammer Regalia." }
entries[267279] = { ["name"] = "Embers of Al'ar", ["text"] = "Binds when picked up\nToy\nClasses: Hunter\nUse: Transform your Hunter Pet into a Phoenix.\n\nDoes not function in Arenas or Battlegrounds. (1 Min Cooldown)" }
entries[267294] = { ["name"] = "Ensemble: Stormstout's Sha-Touched", ["text"] = "Binds when picked up\nUse: Collect the appearances of the Stormstout's Sha-Touched Collection" }
entries[267332] = { ["name"] = "Commendation of Valor", ["text"] = "Binds when picked up\nUse: Awards yourself 10 Valor points\n\"No longer usable after the arrival of the Thunder King.\"" }
